-- Bring the committed 0009 schema forward to the current Prisma shape without rewriting history.
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "isActive" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "tokenVersion" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "product_categories" ADD COLUMN IF NOT EXISTS "classificationGroup" VARCHAR(255);
ALTER TABLE "product_categories" ADD COLUMN IF NOT EXISTS "classificationSubgroup" VARCHAR(255);
ALTER TABLE "criteria" ADD COLUMN IF NOT EXISTS "sectionCode" VARCHAR(1);
ALTER TABLE "criteria" ADD COLUMN IF NOT EXISTS "sectionName" VARCHAR(255);
ALTER TABLE "sub_criteria" ADD COLUMN IF NOT EXISTS "code" VARCHAR(50);
ALTER TABLE "score_options" ADD COLUMN IF NOT EXISTS "order" INTEGER;
ALTER TABLE "products" ADD COLUMN IF NOT EXISTS "submittedAt" TIMESTAMPTZ(3);
CREATE TABLE IF NOT EXISTS "audit_logs" (
    "id" TEXT NOT NULL, "actorId" TEXT, "action" VARCHAR(100) NOT NULL, "entityType" VARCHAR(100) NOT NULL,
    "entityId" VARCHAR(100), "beforeData" JSONB, "afterData" JSONB, "reason" VARCHAR(255),
    "ipAddress" VARCHAR(45), "userAgent" VARCHAR(500), "requestId" VARCHAR(100),
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "audit_logs_actorId_createdAt_idx" ON "audit_logs"("actorId", "createdAt");
CREATE INDEX IF NOT EXISTS "audit_logs_entityType_entityId_createdAt_idx" ON "audit_logs"("entityType", "entityId", "createdAt");
CREATE UNIQUE INDEX IF NOT EXISTS "sub_criteria_criterionId_code_key" ON "sub_criteria"("criterionId", "code");
CREATE UNIQUE INDEX IF NOT EXISTS "score_options_subCriterionId_order_key" ON "score_options"("subCriterionId", "order");
DROP INDEX IF EXISTS "score_options_subCriterionId_points_key";
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'audit_logs_actorId_fkey' AND conrelid = 'audit_logs'::regclass) THEN
        ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_actorId_fkey"
          FOREIGN KEY ("actorId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
    END IF;
END $$;
CREATE TEMP TABLE _seed_categories ("id" TEXT PRIMARY KEY, "classificationGroup" TEXT NOT NULL, "classificationSubgroup" TEXT);
CREATE TEMP TABLE _seed_criteria ("categoryId" TEXT NOT NULL, "code" TEXT NOT NULL, "sectionCode" TEXT NOT NULL, "sectionName" TEXT NOT NULL);
CREATE TEMP TABLE _seed_subcriteria ("categoryId" TEXT NOT NULL, "criterionCode" TEXT NOT NULL, "code" TEXT NOT NULL, "order" INTEGER NOT NULL);
CREATE TEMP TABLE _seed_options ("categoryId" TEXT NOT NULL, "criterionCode" TEXT NOT NULL, "subCode" TEXT NOT NULL, "label" TEXT NOT NULL, "points" INTEGER NOT NULL, "order" INTEGER NOT NULL);
