('fresh-animal-products','1','1.1','Sản phẩm được nuôi, đánh bắt trên địa bàn cấp xã, nhưng có tỷ lệ dưới 50%',1,1),
('fresh-animal-products','1','1.1','Sản phẩm được nuôi, đánh bắt trên địa bàn cấp xã từ 50% đến dưới 75%',2,2),
('fresh-animal-products','1','1.1','Sản phẩm được nuôi, đánh bắt trên địa bàn cấp xã từ 75% đến 100%',3,3),
('fresh-animal-products','1','1.2','Sơ chế (rửa, làm sạch, phân loại, đóng gói...) thủ công',1,1),
