('fresh-animal-products','1','1.5','Có hợp đồng liên kết trên 75% sản lượng tiêu thụ và tổ chức thực hiện hợp đồng ổn định từ 12 tháng trở lên tính đến thời điểm đăng ký đánh giá, phân hạng OCOP*****',3,4),
('fresh-animal-products','1','1.6','Có Hồ sơ, thủ tục về môi trường theo quy định của pháp luật và các quy định khác về bảo vệ môi trường****',1,1),
('fresh-animal-products','1','1.6','Có Hồ sơ, thủ tục về môi trường theo quy định của pháp luật về bảo vệ môi trường và hồ sơ minh chứng về công trình thu gom và xử lý chất thải theo quy định',2,2),
('fresh-animal-products','1','1.6','Có Hồ sơ, thủ tục về môi trường theo quy định của pháp luật về bảo vệ môi trường; hồ sơ minh chứng về công trình thu gom và xử lý chất thải theo quy định và hồ sơ minh chứng về sử dụng bao gói thân thiện với môi trường',3,3),
('fresh-animal-products','1','1.7','Không sử dụng công nghệ theo hướng bền vững trong sản xuất',0,1),
('fresh-animal-products','1','1.7','Có áp dụng công nghệ theo hướng bền vững môi trường (công nghệ tiết kiệm nguyên liệu, nhiên liệu; hoạt động xử lý/tái chế chất thải; tận thu tái sử dụng, tái chế phụ phẩm nông nghiệp,...)',1,2),
('fresh-animal-products','2','2.1','Sản phẩm được nuôi trồng, đánh bắt phổ biến ở nhiều tỉnh, thành phố',0,1),
('fresh-animal-products','2','2.1','Sản phẩm được trồng phổ biến ở nhiều tỉnh, thành phố nhưng có chất lượng nổi trội, khác biệt do điều kiện đất đai, thời tiết, kỹ thuật bản địa',1,2),
('fresh-animal-products','2','2.1','Sản phẩm được nuôi trồng, đánh bắt ở nhiều nơi trên địa bàn, là sản phẩm đặc trưng của tỉnh, có chất lượng nổi trội, thương mại gắn với chỉ dẫn nguồn gốc địa lý****',3,3),
('fresh-animal-products','2','2.2','Đóng gói theo hình thức thông thường, không có bao bì',0,1),
('fresh-animal-products','2','2.2','Đóng gói theo hình thức thông thường, bao bì đơn giản',1,2),
('fresh-animal-products','2','2.2','Đóng gói sáng tạo, bao bì đẹp***',2,3),
('fresh-animal-products','2','2.2','Đóng gói sáng tạo, tiện lợi, bao bì đẹp, sang trọng',3,4),
('fresh-animal-products','2','2.3','Có nhãn, ghi nhãn hàng hóa đầy đủ, theo đúng quy định***',1,1),
('fresh-animal-products','2','2.3','Ghi nhãn hàng hóa đầy đủ, đúng quy định và thể hiện được thông điệp câu chuyện sản phẩm (hình ảnh hoặc lời giới thiệu)',2,2),
('fresh-animal-products','2','2.3','Ghi nhãn hàng hóa đầy đủ, đúng quy định, đẹp và thể hiện được thông điệp câu chuyện sản phẩm (hình ảnh hoặc lời giới thiệu) và có mã truy xuất nguồn gốc điện tử****',3,3),
('fresh-animal-products','2','2.4','Ghi nhãn hàng hóa có sử dụng song ngữ (Việt - Anh hoặc ngôn ngữ nước ngoài khác)',1,1),
('fresh-animal-products','3','3.1','Hộ sản xuất/hộ gia đình có đăng ký kinh doanh; hoặc trang trại; hoặc tổ hợp tác (có giấy đăng ký kinh doanh theo quy định)',1,1),
('fresh-animal-products','3','3.1','Công ty TNHH; hoặc doanh nghiệp tư nhân; hoặc công ty cổ phần có vốn góp của cộng đồng người địa phương <51%',2,2),
('fresh-animal-products','3','3.1','HTX tổ chức, hoạt động theo đúng quy định của pháp luật; hoặc công ty cổ phần có vốn góp của cộng đồng người địa phương ≥ 51%',3,3),
('fresh-animal-products','3','3.2','Đại diện pháp luật của chủ thể không phải nữ, không phải là đồng bào dân tộc thiểu số, không phải là người khuyết tật',0,1),
('fresh-animal-products','3','3.2','Đại diện pháp luật của chủ thể là nữ; hoặc là đồng bào dân tộc thiểu số; hoặc là người khuyết tật',1,2),
('fresh-animal-products','3','3.3','Có sử dụng từ 25% đến dưới 50% lao động là người trên địa bàn cấp xã',1,1),
('fresh-animal-products','3','3.3','Có sử dụng từ 50% đến 75% lao động là người trên địa bàn cấp xã',2,2),
('fresh-animal-products','3','3.3','Có sử dụng ≥ 75% lao động là người trên địa bàn cấp xã',3,3),
('fresh-animal-products','3','3.4','Hợp tác xã xếp loại trung bình hoặc năm trước liền kề năm đánh giá có lợi nhuận cao hơn so với năm trước liền kề; các loại hình khác: Năm trước liền kề năm đánh giá có lợi nhuận cao hơn so với năm trước liền kề.',1,1),
('fresh-animal-products','3','3.4','Hợp tác xã xếp loại khá trở lên hoặc có 02 năm liên tiếp tăng trưởng dương về lợi nhuận tính từ năm trước liền kề năm đánh giá; các loại hình khác: Có 02 năm liên tiếp tăng trưởng dương về lợi nhuận tính từ năm trước liền kề năm đánh giá****',2,2),
('fresh-animal-products','3','3.5','Đơn đăng ký nhãn hiệu đã được cơ quan có thẩm quyền chấp nhận hoặc công bố (đã qua vòng thẩm định hình thức)***',1,1),
('fresh-animal-products','3','3.5','Các nhãn hiệu sử dụng trên bao bì, nhãn của sản phẩm được cấp Giấy chứng nhận đăng ký nhãn hiệu và sản phẩm có sử dụng dấu hiệu chỉ dẫn nguồn gốc địa lý gắn với cộng đồng địa phương (trường hợp sản phẩm đã được nhà nước bảo hộ chỉ dẫn địa lý, nhãn hiệu tập thể, nhãn hiệu chứng nhận thì phải có văn bản ghi nhận quyền sử dụng)****',2,2),
('fresh-animal-products','3','3.5','Các nhãn hiệu sử dụng trên bao bì, nhãn của sản phẩm được cấp Giấy chứng nhận đăng ký nhãn hiệu và sản phẩm có sử dụng dấu hiệu chỉ dẫn nguồn gốc địa lý gắn với cộng đồng địa phương (trường hợp sản phẩm đã được nhà nước bảo hộ chỉ dẫn địa lý, nhãn hiệu tập thể, nhãn hiệu chứng nhận thì phải có văn bản ghi nhận quyền sử dụng) và có Bằng độc quyền kiểu dáng công nghiệp, hoặc Bằng sáng chế, hoặc Bằng độc quyền giải pháp hữu ích, hoặc Giấy chứng nhận đăng ký quyền tác giả (trừ Giấy chứng nhận đăng ký quyền tác giả đối với nhãn hiệu).',3,3),
('fresh-animal-products','4','4.1','Thị trường trong địa bàn cấp xã',1,1),
('fresh-animal-products','4','4.1','Thị trường ngoài địa bàn cấp xã, có dưới 5 đại diện/đại lý phân phối***',2,2),
('fresh-animal-products','4','4.1','Thị trường ngoài địa bàn cấp xã, có ≥ 5 đại diện/đại lý phân phối****',3,3),
('fresh-animal-products','4','4.1','Thị trường quốc tế (có hợp đồng và tài liệu minh chứng thực hiện hợp đồng) hoặc phân phối tại các kênh thương mại hiện đại: siêu thị, thương mại điện tử,... (có hợp đồng và tài liệu minh chứng thực hiện hợp đồng, đường dẫn gian hàng điện tử)*****',5,4),
('fresh-animal-products','4','4.2','Không có người chịu trách nhiệm quản lý phân phối',0,1),
