UPDATE "product_categories" c SET "classificationGroup" = s."classificationGroup", "classificationSubgroup" = s."classificationSubgroup" FROM _seed_categories s WHERE c."id" = s."id";
UPDATE "criteria" c SET "sectionCode" = s."sectionCode", "sectionName" = s."sectionName" FROM "criteria_sets" cs, _seed_criteria s WHERE cs."categoryId" = s."categoryId" AND c."setId" = cs."id" AND c."code" = s."code";
UPDATE "sub_criteria" sc SET "code" = s."code" FROM "criteria" c, "criteria_sets" cs, _seed_subcriteria s WHERE sc."criterionId" = c."id" AND c."setId" = cs."id" AND cs."categoryId" = s."categoryId" AND c."code" = s."criterionCode" AND sc."order" = s."order";
UPDATE "score_options" so SET "order" = s."order" FROM "sub_criteria" sc, "criteria" c, "criteria_sets" cs, _seed_options s WHERE so."subCriterionId" = sc."id" AND sc."criterionId" = c."id" AND c."setId" = cs."id" AND cs."categoryId" = s."categoryId" AND c."code" = s."criterionCode" AND sc."code" = s."subCode" AND so."label" = s."label" AND so."points" = s."points";
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM "product_categories" WHERE "classificationGroup" IS NULL)
       OR EXISTS (SELECT 1 FROM "criteria" WHERE "sectionCode" IS NULL OR "sectionName" IS NULL)
       OR EXISTS (SELECT 1 FROM "sub_criteria" WHERE "code" IS NULL)
       OR EXISTS (SELECT 1 FROM "score_options" WHERE "order" IS NULL) THEN
        RAISE EXCEPTION '0010 cannot map existing OCOP criteria rows to the official seed; no rows were deleted';
    END IF;
END $$;
ALTER TABLE "product_categories" ALTER COLUMN "classificationGroup" SET NOT NULL;
ALTER TABLE "criteria" ALTER COLUMN "sectionCode" SET NOT NULL;
ALTER TABLE "criteria" ALTER COLUMN "sectionName" SET NOT NULL;
ALTER TABLE "sub_criteria" ALTER COLUMN "code" SET NOT NULL;
ALTER TABLE "score_options" ALTER COLUMN "order" SET NOT NULL;
DROP TABLE _seed_options;
DROP TABLE _seed_subcriteria;
DROP TABLE _seed_criteria;
DROP TABLE _seed_categories;